// Product pages (/products/<slug>/), their schema.org data, the Google
// Merchant feed (google-feed.tsv) and the sitemap, all generated by
// scripts/build-product-pages.js from products.js + product-seo.js.
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const test = require("node:test");
const vm = require("node:vm");
const { PRODUCTS, activeSalePrice } = require("../products.js");
const seo = require("../product-seo.js");
const links = require("../product-links.js");
const builder = require("../scripts/build-product-pages.js");
const pageJs = require("../product-page.js");

const root = path.join(__dirname, "..");
const read = (f) => fs.readFileSync(path.join(root, f), "utf8");
const app = read("app.js");
const index = read("index.html");
const visible = PRODUCTS.filter((p) => !p.hidden);
const FEED_IDS_OCT30 = 239; // items in the cigco-feed.tsv uploaded to Merchant Center on Oct 30

function fnSource(name) {
  const start = app.indexOf(`function ${name}(`);
  assert.ok(start >= 0, `app.js defines ${name}`);
  return app.slice(start, app.indexOf("\n}\n", start) + 2);
}
function appHelpers(nowMs) {
  const ctx = { PRODUCTS, activeSalePrice, Date: { now: () => nowMs, parse: Date.parse } };
  vm.runInNewContext(["styleObj", "optionPriceFor", "salePriceNow", "currentPrice", "componentVariantStock", "variantStock"].map(fnSource).join("\n") +
    "\nthis.api = { currentPrice, variantStock };", ctx);
  return ctx.api;
}
function jsonLdBlocks(html) {
  return [...html.matchAll(/<script type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)].map((m) => JSON.parse(m[1]));
}
function parseTsv(tsv) {
  const [head, ...rows] = tsv.trim().split("\n").map((l) => l.split("\t"));
  return rows.map((r) => Object.fromEntries(head.map((h, i) => [h, r[i]])));
}
const variantMatches = (v, pick) => ["style", "color", "size"].every((k) => !pick[k] || v[k] === pick[k]);
const BANNED = /\b(cig|cigs|cigar|cigars|cigarette|cigarettes|smoke|smoking|tobacco|vape|vaping)\b/i;

test("every visible product gets its own page at a unique clean URL", () => {
  const slugs = visible.map((p) => seo.productSlug(p));
  assert.equal(new Set(slugs).size, slugs.length);
  for (const p of visible) {
    assert.match(seo.productSlug(p), /^[a-z0-9]+(-[a-z0-9]+)*$/);
    assert.equal(seo.productPageUrl(p), `https://cigcompany.com/products/${seo.productSlug(p)}/`);
    assert.ok(fs.existsSync(path.join(root, "products", seo.productSlug(p), "index.html")), p.id);
  }
  assert.deepEqual(fs.readdirSync(path.join(root, "products")).sort(), slugs.slice().sort(), "no stale page folders");
  for (const p of PRODUCTS.filter((x) => x.hidden)) assert.ok(!seo.pageProducts(PRODUCTS).includes(p));
});

test("committed pages, feed, sitemap and homepage links match a fresh build", async () => {
  const out = await builder.build({ write: false });
  for (const pg of out.pages) assert.equal(read(pg.file), pg.html, `${pg.file} is stale: run node scripts/build-product-pages.js`);
  assert.equal(read("google-feed.tsv"), out.feed, "google-feed.tsv is stale: run node scripts/build-product-pages.js");
  assert.equal(read("sitemap.xml"), out.sitemap);
  assert.equal(index, out.index);
});

test("each page: unique title/description, canonical, og/twitter image, visible name, price, options and info@ contact", () => {
  const titles = new Set(), descs = new Set();
  for (const p of visible) {
    const html = read(`products/${seo.productSlug(p)}/index.html`);
    const url = seo.productPageUrl(p);
    const title = html.match(/<title>([^<]+)<\/title>/)[1];
    const desc = html.match(/<meta name="description" content="([^"]+)"/)[1];
    titles.add(title); descs.add(desc);
    assert.ok(!BANNED.test(title) && !BANNED.test(desc), `${p.id}: ${title} / ${desc}`);
    assert.ok(html.includes(`<link rel="canonical" href="${url}" />`));
    assert.ok(html.includes(`<meta property="og:url" content="${url}" />`));
    assert.match(html, /<meta property="og:image" content="https:\/\/cigcompany\.com\/assets\/[^"]+\.(jpg|jpeg|png|webp)" \/>/i);
    assert.match(html, /<meta name="twitter:image" content="https:\/\/cigcompany\.com\/assets\//);
    assert.ok(html.includes(`<h1 class="pd-name">${seo.seoName(p).replace(/&/g, "&amp;")}</h1>`), p.id);
    assert.match(html, /id="pp-price">[^<]*\$\d+\.\d\d|id="pp-price"><span class="price-strike">/);
    assert.ok(html.includes(`data-product-id="${p.id}"`));
    for (const c of (p.colors || []).map((x) => (typeof x === "string" ? x : x.name))) {
      assert.ok(html.includes(`data-value="${c}"`), `${p.id} color ${c}`);
    }
    assert.ok(html.includes("mailto:info@cigcompany.com"));
    assert.ok(!html.includes("orders@cigcompany.com"));
    assert.ok(!/8\.95|over \$75/.test(html), `${p.id}: no old mask shipping fee`);
    // Every referenced local image exists (no new artwork, reuse what's there).
    for (const m of html.matchAll(/(?:src|content)="(?:https:\/\/cigcompany\.com)?\/(assets\/[^"?]+)"/g)) {
      assert.ok(fs.existsSync(path.join(root, m[1])), `${p.id}: ${m[1]} exists`);
    }
    for (const s of ["/checkout-attribution.js", "/products.js", "/product-links.js", "/product-seo.js", "/live-stock-client.js", "/product-page.js"]) {
      assert.ok(html.includes(`<script src="${s}"></script>`), `${p.id} loads ${s}`);
    }
  }
  assert.equal(titles.size, visible.length);
  assert.equal(descs.size, visible.length);
});

test("buy button hands off to the shop pop-up (/?product=ID...), keeping ?src / utm tags", () => {
  for (const p of visible) {
    const html = read(`products/${seo.productSlug(p)}/index.html`);
    const href = html.match(/id="pp-buy" href="([^"]+)"/)[1].replace(/&amp;/g, "&");
    assert.ok(href.startsWith(`/?product=${encodeURIComponent(p.id)}`), href);
    const parsed = links.parseProductLink(href.slice(1), PRODUCTS);
    assert.equal(parsed && parsed.id, p.id, `${href} opens ${p.id}`);
  }
  const ski = PRODUCTS.find((p) => p.id === "0008");
  const attribution = pageJs.attributionParams("?color=Gold&size=3-Hole&src=google&utm_campaign=fw26&foo=1");
  assert.deepEqual(attribution, { src: "google", utm_campaign: "fw26" });
  const pick = pageJs.pickFromSearch(ski, PRODUCTS, seo, links, "?color=Gold&size=3-Hole&src=google");
  assert.equal(pick.color, "Gold"); assert.equal(pick.size, "3-Hole");
  assert.equal(pageJs.buyHref(ski, pick, links, attribution), "/?product=0008&color=Gold&size=3-Hole&src=google&utm_campaign=fw26");
  // A bad variant in the link falls back to the page default.
  const bad = pageJs.pickFromSearch(ski, PRODUCTS, seo, links, "?color=Purple");
  assert.equal(bad.color, seo.pageDefaultPick(ski).color);
});

test("product JSON-LD: ProductGroup with variants, offers, shipping and returns Google can read", () => {
  for (const p of visible) {
    const blocks = jsonLdBlocks(read(`products/${seo.productSlug(p)}/index.html`));
    const g = blocks.find((b) => b["@type"] === "ProductGroup");
    assert.ok(g, p.id);
    assert.ok(blocks.some((b) => b["@type"] === "BreadcrumbList"));
    assert.equal(g["@context"], "https://schema.org");
    assert.equal(g.name, seo.seoName(p));
    assert.ok(!BANNED.test(g.name) && !BANNED.test(g.description), p.id);
    assert.ok(g.description.length > 30);
    assert.deepEqual(g.brand, { "@type": "Brand", name: "CIG & CO." });
    assert.equal(g.url, seo.productPageUrl(p));
    const imgs = [].concat(g.image);
    assert.ok(imgs.length && imgs.every((u) => u.startsWith("https://cigcompany.com/")), p.id);
    assert.ok(g.hasVariant.length >= 1);
    const skus = new Set();
    for (const v of g.hasVariant) {
      assert.equal(v["@type"], "Product");
      assert.ok(v.name && v.sku && v.image);
      assert.ok(!BANNED.test(v.name), v.name);
      skus.add(v.sku);
      const o = v.offers;
      assert.equal(o["@type"], "Offer");
      assert.equal(o.priceCurrency, "USD");
      assert.match(String(o.price), /^\d+(\.\d\d)?$/);
      assert.ok(Number(o.price) > 0);
      assert.match(o.availability, /^https:\/\/schema\.org\/(InStock|OutOfStock)$/);
      assert.ok(o.url.startsWith(seo.productPageUrl(p)));
      assert.equal(o.itemCondition, "https://schema.org/NewCondition");
      const ship = o.shippingDetails;
      assert.equal(ship["@type"], "OfferShippingDetails");
      assert.equal(ship.shippingDestination.addressCountry, "US");
      assert.equal(ship.shippingRate.currency, "USD");
      assert.equal(ship.shippingRate.value, 0, "free US shipping on everything (masks since 2026-11-01)");
      if (p.liveStock) {
        const dt = ship.deliveryTime;
        assert.equal(dt.handlingTime.minValue + dt.transitTime.minValue, 5);
        assert.equal(dt.handlingTime.maxValue + dt.transitTime.maxValue, 14);
      }
      assert.ok(ship.deliveryTime.handlingTime.maxValue >= 1 && ship.deliveryTime.transitTime.maxValue >= 1);
      const ret = o.hasMerchantReturnPolicy;
      assert.equal(ret["@type"], "MerchantReturnPolicy");
      assert.equal(ret.applicableCountry, "US");
      if (p.liveStock) {
        assert.equal(ret.returnPolicyCategory, "https://schema.org/MerchantReturnFiniteReturnWindow");
        assert.equal(ret.merchantReturnDays, 14);
      } else {
        assert.equal(ret.returnPolicyCategory, "https://schema.org/MerchantReturnNotPermitted");
      }
    }
    assert.equal(skus.size, g.hasVariant.length, `${p.id}: unique skus`);
    if (g.hasVariant.length > 1) assert.ok(g.variesBy.length >= 1);
  }
});

test("price and stock in the Google data are exactly what the shop charges/allows", () => {
  for (const now of [Date.now(), Date.parse("2026-10-31T16:00:00Z"), Date.parse("2026-12-01T00:00:00Z")]) {
    const shop = appHelpers(now);
    for (const p of visible) for (const v of seo.variants(p)) {
      assert.equal(seo.priceNow(p, v, now), shop.currentPrice(p, v.style, v.color, v.size, now), `${p.id} ${JSON.stringify(v)}`);
      const shopStock = shop.variantStock(p, v.style, v.color, v.size);
      assert.equal(seo.stockFor(p, v), shopStock, `${p.id} ${JSON.stringify(v)}`);
    }
  }
});

test("Google feed: same item ids as the Oct 30 upload, clean titles, brand, live prices, ?src=google links", () => {
  const rows = parseTsv(read("google-feed.tsv"));
  assert.deepEqual(Object.keys(rows[0]), seo.FEED_COLUMNS);
  const ids = rows.map((r) => r.id);
  assert.equal(new Set(ids).size, ids.length);
  assert.ok(ids.length >= FEED_IDS_OCT30);
  // Spot-check ids the old feed used (so Merchant Center updates, not duplicates).
  for (const id of ["0005-RED", "0008-RED-1-HOLE", "0013-PURPLE", "FW26-BAG-BLACK", "FW26-CASE-BLACK-IPHONE-16-PRO", "FW26-SLEEVE-BLACK-13IN", "FW26-TOTE-BLACK"]) {
    assert.ok(ids.includes(id), id);
  }
  const shop = appHelpers(Date.now());
  for (const r of rows) {
    assert.ok(!BANNED.test(r.title), r.title);
    assert.ok(!BANNED.test(r.description), r.id);
    assert.ok(r.title.length <= 150 && r.description.length <= 5000);
    assert.equal(r.brand, "CIG & CO.");
    assert.equal(r.condition, "new");
    assert.equal(r.identifier_exists, "no");
    assert.match(r.availability, /^(in_stock|out_of_stock)$/);
    assert.match(r.price, /^\d+\.\d\d USD$/);
    assert.equal(r.shipping, "US:::0.00 USD", r.id);
    assert.match(r.google_product_category, /^\d+$/);
    const u = new URL(r.link);
    assert.equal(u.origin, "https://cigcompany.com");
    assert.equal(u.searchParams.get("src"), "google");
    const slug = u.pathname.match(/^\/products\/([a-z0-9-]+)\/$/)[1];
    assert.ok(fs.existsSync(path.join(root, "products", slug, "index.html")), r.link);
    assert.ok(r.image_link.startsWith("https://cigcompany.com/assets/"));
    assert.ok(fs.existsSync(path.join(root, new URL(r.image_link).pathname)), r.image_link);
    // The link's variant is a real pick, priced the same as the row.
    const p = PRODUCTS.find((x) => x.id === r.item_group_id);
    assert.ok(p && !p.hidden && !p.soldOut, r.id);
    const pick = { style: u.searchParams.get("style"), color: u.searchParams.get("color"), size: u.searchParams.get("size") };
    // Size-less links (e.g. the case: model is picked in the pop-up) price the same for any size.
    const size = pick.size || (seo.variants(p).find((v) => variantMatches(v, pick)) || {}).size || null;
    const charged = shop.currentPrice(p, pick.style, pick.color, size);
    assert.equal(r.sale_price ? r.sale_price : r.price, `${charged.toFixed(2)} USD`, r.id);
    if (pick.size || !seo.sizeMatters(p)) {
      assert.equal(r.availability === "in_stock", shop.variantStock(p, pick.style, pick.color, size) > 0, r.id);
    }
  }
});

test("sitemap lists every product page; homepage links them with real <a href>", () => {
  const sitemap = read("sitemap.xml");
  assert.ok(sitemap.includes("<loc>https://cigcompany.com/</loc>"));
  for (const p of visible) {
    assert.ok(sitemap.includes(`<loc>${seo.productPageUrl(p)}</loc>`), p.id);
    assert.ok(index.includes(`href="${seo.productPagePath(p)}"`), `homepage links ${p.id}`);
  }
  assert.ok(index.indexOf('<script src="product-seo.js"></script>') < index.indexOf('<script src="app.js"></script>'));
  assert.match(fnSource("renderProductGrid"), /product-card-link/);
  const ld = seo.catalogItemListJsonLd(PRODUCTS);
  assert.equal(ld["@type"], "ItemList");
  assert.deepEqual(ld.itemListElement.map((i) => i.url), visible.map((p) => seo.productPageUrl(p)));
});

test("Google-facing names never say CIG; shop names in products.js are untouched", () => {
  for (const p of visible) {
    assert.ok(!BANNED.test(seo.seoName(p)), seo.seoName(p));
    for (const v of seo.variants(p)) assert.ok(!BANNED.test(seo.variantTitle(p, v)), seo.variantTitle(p, v));
  }
  assert.equal(PRODUCTS.find((p) => p.id === "0008").name, "CIG Ski Mask");
  globalThis.CIGProductSeo = seo;
  try {
    const ld = links.productJsonLd(PRODUCTS.find((p) => p.id === "0008"), { color: "Red", size: "1-Hole" }, {
      priceFor: () => 30, stockFor: () => 5, imageFor: () => "assets/products/skimask-red-1hole.jpg",
    });
    assert.equal(ld.name, "Paisley Bandana Print Ski Mask (Red / 1-Hole)");
    assert.deepEqual(ld.brand, { "@type": "Brand", name: "CIG & CO." });
  } finally { delete globalThis.CIGProductSeo; }
});
